mapper.select:
select count(1)
from hm_windturbine_info
where windfarm = #{windfarm};

select count(1)
from hm_windturbine_info
where windfarm = #{windfarm}
  and status = #{status};

select windturbine
from hm_windturbine_info
where windfarm = #{windfarm};

select windturbine
from hm_windturbine_info
where windfarm = #{windfarm}
  and status = #{status};

select windturbine, status
from hm_windturbine_info
where windfarm = #{windfarm};
